// Edificios de los Puestos Centrales de Control 265. Apartado nuevo del menú: se elige P.C.C. 1 o
// P.C.C. 2 y se recorre el edificio por fuera y piso por piso. La distribución por pisos y las listas
// de equipo salen de las diapositivas «Edificio del P.C.C. 1» del material del curso (METRO 7EM1).
// Las medidas y el acomodo dentro de cada piso son ilustrativos: el material da listas, no planos.
import * as THREE from 'three';
export const SOURCE265='Material del curso de Tracción Eléctrica, presentación METRO 7EM1: «Edificio del P.C.C. 1», subestación Buen Tono de 85/15 kV y diagrama unifilar de la subestación de alumbrado y fuerza del P.C.C. 2.';
export const ASSUMED265=Object.freeze({side:44,basement:5,ground:7,storey:4.2,note:'Las medidas del edificio y la posición de cada equipo dentro de su piso son ilustrativas. El material dice qué hay en cada piso, no dónde va cada cosa. Sí documenta que en el sótano el lado norte es de 85 kV y el sur de servicios, y que las subestaciones A y B están en lados opuestos.'});
// Pisos del P.C.C. 1, de abajo hacia arriba, tal como los rotulan las diapositivas.
