export function floorBase265(i){const A=ASSUMED265;return i===0?-A.basement:i===1?0:A.ground+(i-2)*A.storey;}
export function floorHeight265(i){const A=ASSUMED265;return i===0?A.basement:i===1?A.ground:A.storey;}

const mats=new Map();
function mat(color,o={}){const k=color+JSON.stringify(o);if(!mats.has(k))mats.set(k,new THREE.MeshStandardMaterial({color,roughness:.75,metalness:.1,...o}));return mats.get(k);}
function box(g,w,h,d,color,x,y,z,name,o){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(color,o));m.position.set(x,y+h/2,z);if(name)m.name=name;g.add(m);return m;}
function cyl(g,r,h,color,x,y,z,name,rot){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,18),mat(color));m.position.set(x,y+(rot?r:h/2),z);if(rot==='x')m.rotation.z=Math.PI/2;if(rot==='z')m.rotation.x=Math.PI/2;if(name)m.name=name;g.add(m);return m;}
function label(g,text,x,y,z,scale=1){let tex=null;if(typeof document!=='undefined'&&document.createElement){const c=document.createElement('canvas'),ctx=c.getContext?.('2d');if(ctx){c.width=512;c.height=96;ctx.fillStyle='#0d1a20e6';ctx.fillRect(0,0,512,96);ctx.strokeStyle='#79dbc1';ctx.lineWidth=4;ctx.strokeRect(2,2,508,92);ctx.fillStyle='#f2f6f4';let px=34;do{ctx.font=`600 ${px}px system-ui,sans-serif`;px-=2;}while(ctx.measureText(text).width>490&&px>14);ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,256,50);tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;}}
 const s=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,color:tex?0xffffff:0x79dbc1,depthTest:false,transparent:true}));s.scale.set(10.5*scale,1.97*scale,1);s.position.set(x,y,z);s.name='Rotulo:'+text;s.renderOrder=5;g.add(s);return s;}
function rows(g,nx,nz,w,h,d,color,x0,z0,dx,dz,y,name){for(let i=0;i<nx;i++)for(let j=0;j<nz;j++)box(g,w,h,d,color,x0+i*dx,y,z0+j*dz,name);}

